// TrueType rasteriser (cmap formats 4/12, glyf outlines, 4x4-supersampled
// non-zero fill). The faces are the system Noto Serif / Noto Sans (SIL
// OFL 1.1), subsetted to printable ASCII plus · – — •, so the program
// stays fully self-contained: no system font lookup, no network, and the
// render is a pure function of this file — two runs write identical bytes.
// Text is placed by baseline: drawText's y is the baseline of the text.
